     1	package imagesearch
     2	
     3	import (
     4		"context"
     5		"encoding/json"
     6		"fmt"
     7		"io"
     8		"net/http"
     9		"net/url"
    10		"regexp"
    11		"strconv"
    12		"strings"
    13		"time"
    14		"unicode"
    15	
    16		"github.com/charmbracelet/x/ansi"
    17	
    18		"github.com/anthnel/devdesk/internal/oci"
    19	)
    20	
    21	// hubSearchURL is the v1 search endpoint `docker search` uses; not a public
    22	// Hub contract.
    23	var hubSearchURL = "https://index.docker.io/v1/search"
    24	
    25	// HubLimit is the validated cap: one request, one page.
    26	const HubLimit = 50
    27	
    28	// hubMaxBody caps what is read from the response.
    29	const hubMaxBody = 1 << 20
    30	
    31	// hubComponent is one path component of a repository name: lowercase
    32	// alphanumerics joined by single '.', '_' or '-' separators.
    33	var hubComponent = regexp.MustCompile(`^[a-z0-9]+(?:[._-][a-z0-9]+)*$`)
    34	
    35	// HubSearcher searches Docker Hub anonymously: one GET, no credentials, no
    36	// pagination. Whatever Target carries for authentication is ignored.
    37	type HubSearcher struct {
    38		// Endpoint overrides hubSearchURL when set.
    39		Endpoint string
    40		// Client overrides the default client (15 s timeout, no redirects).
    41		Client *http.Client
    42	}
    43	
    44	type hubResponse struct {
    45		Results []struct {
    46			Name        string `json:"name"`
    47			Description string `json:"description"`
    48			IsOfficial  bool   `json:"is_official"`
    49			StarCount   *int   `json:"star_count"`
    50		} `json:"results"`
    51	}
    52	
    53	// Search runs one anonymous search. A non-200 answer is an *oci.StatusError.
    54	func (h HubSearcher) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
    55		limit := q.Limit
    56		if limit <= 0 || limit > HubLimit {
    57			limit = HubLimit
    58		}
    59		endpoint := h.Endpoint
    60		if endpoint == "" {
    61			endpoint = hubSearchURL
    62		}
    63		u, err := url.Parse(endpoint)
    64		if err != nil {
    65			return nil, false, fmt.Errorf("hub search: %w", err)
    66		}
    67		vals := u.Query()
    68		vals.Set("q", q.Text)
    69		vals.Set("n", strconv.Itoa(limit))
    70		u.RawQuery = vals.Encode()
    71	
    72		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
    73		if err != nil {
    74			return nil, false, fmt.Errorf("hub search: %w", err)
    75		}
    76		client := h.Client
    77		if client == nil {
    78			client = &http.Client{
    79				Timeout: 15 * time.Second,
    80				CheckRedirect: func(*http.Request, []*http.Request) error {
    81					return http.ErrUseLastResponse
    82				},
    83			}
    84		}
    85		resp, err := client.Do(req)
    86		if err != nil {
    87			return nil, false, fmt.Errorf("hub search: %w", err)
    88		}
    89		defer func() { _ = resp.Body.Close() }()
    90		if resp.StatusCode != http.StatusOK {
    91			return nil, false, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceRegistry}
    92		}
    93		body, err := io.ReadAll(io.LimitReader(resp.Body, hubMaxBody+1))
    94		if err != nil {
    95			return nil, false, fmt.Errorf("hub search: %w", err)
    96		}
    97		if len(body) > hubMaxBody {
    98			return nil, false, fmt.Errorf("hub search: response over %d bytes", hubMaxBody)
    99		}
   100		var parsed hubResponse
   101		if err := json.Unmarshal(body, &parsed); err != nil {
   102			return nil, false, fmt.Errorf("hub search: %w", err)
   103		}
   104	
   105		prefix := strings.Trim(t.RepoPrefix, "/")
   106		var out []Image
   107		for _, r := range parsed.Results {
   108			repo, ok := hubRepo(r.Name)
   109			if !ok {
   110				continue
   111			}
   112			if prefix != "" && !strings.HasPrefix(repo, prefix+"/") {
   113				continue
   114			}
   115			img := Image{
   116				EntryKey:    t.EntryKey,
   117				Name:        strings.TrimPrefix(repo, "library/"),
   118				Repo:        repo,
   119				Description: sanitizeDescription(r.Description),
   120				Official:    r.IsOfficial,
   121			}
   122			if r.StarCount != nil {
   123				img.Stars, img.HasStars = *r.StarCount, true
   124			}
   125			out = append(out, img)
   126			if len(out) == HubLimit {
   127				break
   128			}
   129		}
   130		return out, false, nil
   131	}
   132	
   133	// hubRepo validates a name Hub returned and returns the final repository path:
   134	// a bare name lives under library/ (D39). The name ends up in a docker
   135	// command, so anything that is not a valid repository name is dropped.
   136	func hubRepo(name string) (string, bool) {
   137		if name == "" {
   138			return "", false
   139		}
   140		parts := strings.Split(name, "/")
   141		for _, p := range parts {
   142			if !hubComponent.MatchString(p) {
   143				return "", false
   144			}
   145		}
   146		if len(parts) == 1 {
   147			return "library/" + name, true
   148		}
   149		return name, true
   150	}
   151	
   152	// sanitizeDescription removes escape sequences and control characters (a
   153	// description is remote, untrusted text) and collapses whitespace.
   154	func sanitizeDescription(s string) string {
   155		s = ansi.Strip(s)
   156		s = strings.Map(func(r rune) rune {
   157			switch {
   158			case r == '\t' || r == '\n' || r == '\r':
   159				return ' '
   160			case unicode.IsControl(r):
   161				return -1
   162			}
   163			return r
   164		}, s)
   165		return strings.Join(strings.Fields(s), " ")
   166	}
   167	package imagesearch
   168	
   169	import (
   170		"context"
   171		"errors"
   172	
   173		"github.com/anthnel/devdesk/internal/oci"
   174	)
   175	
   176	// ErrUnsupported: this registry has no search path yet (non-Hub until IS-03,
   177	// dhi.io until IS-17).
   178	var ErrUnsupported = errors.New("image search not supported on this registry")
   179	
   180	// ByRegistry sends a Hub target (oci.IsDockerHub(t.RegistryURL)) to hub, any
   181	// other to other; a nil searcher answers ErrUnsupported without any request.
   182	func ByRegistry(hub, other Searcher) Searcher {
   183		return SearcherFunc(func(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
   184			s := other
   185			if oci.IsDockerHub(t.RegistryURL) {
   186				s = hub
   187			}
   188			if s == nil {
   189				return nil, false, ErrUnsupported
   190			}
   191			return s.Search(ctx, t, q)
   192		})
   193	}
   194	package oci
   195	
   196	import "strings"
   197	
   198	// RegistryHost strips the scheme and the trailing slash from a configured
   199	// registry URL, leaving what Docker itself is keyed on: `host[:port]`, plus
   200	// whatever path a repository manager serves the registry under.
   201	//
   202	// A registry URL is written either way in practice, so every Docker-facing
   203	// use has to strip it (D39): a `docker pull` reference carrying `https://` is
   204	// not a reference at all.
   205	func RegistryHost(registryURL string) string {
   206		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
   207		for _, scheme := range []string{"https://", "http://"} {
   208			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
   209				return base[len(scheme):]
   210			}
   211		}
   212		return base
   213	}
   214	
   215	// IsDockerHub reports whether a configured registry URL names Docker Hub,
   216	// under any spelling: `docker.io` or `registry-1.docker.io`, with or without a
   217	// scheme. Hub is the one registry whose references carry no host, so every
   218	// caller has to recognise it.
   219	func IsDockerHub(registryURL string) bool {
   220		host := RegistryHost(registryURL)
   221		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
   222	}
