// order: the filter bar while it is open, then a confirmed query, then it
// cancels the lot and goes back to the form (which keeps the typed name and
// the selection). The lot's late answers are no longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			return b, nil
		}
		b.cancelInFlight()
		b.gen = nextBrowserGen()
		b.pendingSearches = 0
		b.state = browserStateInput
		b.searchTable.Blur()
		b.updateFocus()
		return b, nil
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	if msg.Err != nil {
		alias := msg.EntryKey
		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
			alias = entryAlias(*e)
		}
		if errors.Is(msg.Err, imagesearch.ErrUnsupported) {
			log.Printf("INFO [oci_resources] image search on %s: %s", alias, msg.Err)
			return m, nil
		}
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, jobs.SafeCause(msg.Err))
	}
	return m, nil
}

// handleRegistryBrowserWarn shows the browser's warning in the footer.
func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
	return m, m.footer.Warn(strings.TrimSpace(msg.Text))
}
package jobs

import (
	"regexp"
)

var (
	// userinfo between "scheme://" and the host: everything up to the LAST "@"
	// before the first "/", so a raw "@" in a password does not leak its tail.
	urlUserinfo = regexp.MustCompile(`(?i)\b([a-z][a-z0-9+.-]*://)[^\s/'"]*@`)
	// the value of a secret-bearing query or fragment parameter, anchored on
	// the "?", "&" or "#" that precedes its name; the value stops at "&", a
	// space, a quote or "#".
	secretParam = regexp.MustCompile(`(?i)([?&#][a-z_-]*(?:token|password|passwd|secret|key)=)[^&\s'"#]*`)
	// the credential of an Authorization or PRIVATE-TOKEN header.
	authHeader = regexp.MustCompile(`(?i)\b(authorization:\s*(?:bearer|basic|token)\s+|private-token:\s*)[^\s'"]+`)
)

// SafeCause renders an error for display and logs with the credentials a URL
// in its text may carry removed: the userinfo of any scheme://, the values of
// secret query parameters (token, password, secret, key families) and the
// credential of Authorization and PRIVATE-TOKEN headers. The scp form (git@host:path) carries no
// secret and is left alone.
func SafeCause(err error) string {
	if err == nil {
		return ""
	}
	s := urlUserinfo.ReplaceAllString(err.Error(), "$1")
	s = secretParam.ReplaceAllString(s, "${1}")
	return authHeader.ReplaceAllString(s, "${1}")
}
